// This file is generated by AI.

// 磁盘变更同步的**判据** (纯函数, 不碰 Tauri / store / 浏览器)。
//
// 一份打开中的文档有三个"内容": 磁盘上的、我们上次知道的磁盘内容 (`baseHash`)、编辑器里现在
// 这一份。只比"磁盘 vs 编辑器"是不够的 —— 那样会出现两种假冲突:
//
// * **自己写盘被当成外部修改**: 自动保存每 800ms 就写一次盘, 写完之后用户接着敲字, 磁盘与
//   编辑器立刻又不同了。没有基准就分不清"这不一样是我刚敲的"还是"别人改了文件";
// * **别处写了同样的内容**: 例如另一个窗口保存了同一份文本, 此时磁盘与编辑器一致, 不需要
//   任何提示 (对应 `adopt`)。
//
// 因此判据是三步: 与基准相同 -> 忽略; 与编辑器相同 -> 只对齐基准; 两者都不同 -> 按脏标记
// 决定"直接重读"还是"冲突裁决"。
//
// 比较前**必须归一化换行**: Windows 上文件是 CRLF, 而 Monaco 的 model 可能按 LF 回过文本,
// 不归一化会让每一次自动保存都变成一次"外部修改"。
//
// 放在纯模块里是为了能在 node 环境直接单测 (见 `tests/disk-state.test.ts`)。

/** 一次磁盘检查的结论。 */
export type DiskAction =
  /** 基准与编辑器内容都不需要更新 (磁盘没变) */
  | 'ignore'
  /** 磁盘内容与编辑器一致: 只把基准对齐, 不碰编辑器 */
  | 'adopt'
  /** 文档没有未保存改动: 直接用磁盘内容覆盖编辑器 */
  | 'reload'
  /** 文档有未保存改动: 交给用户裁决 */
  | 'conflict';

export interface DiskCheckInput {
  /** 刚读到的磁盘内容的哈希 */
  diskHash: string;
  /** 我们已知磁盘上是哪一份的哈希; 未知时为 undefined */
  baseHash: string | undefined;
  /** 编辑器里现在这一份的哈希 */
  memHash: string;
  /** 编辑器里这一份是否有未保存改动 */
  dirty: boolean;
}

/** 归一化换行 (只做 CRLF -> LF; 单独出现的 CR 不处理, 那通常是坏文件)。 */
export function normalizeContent(text: string): string {
  return text.replace(/\r\n/g, '\n');
}

/**
 * 内容哈希 (FNV-1a, 与配音卡的三方比较同一套口径)。
 *
 * 入参**先归一化换行**再算: 调用方不必各自记着这件事, 忘一处就是一堆假冲突。
 * 无密码学强度需求, 只用于"是不是同一份内容"。
 */
export function contentHash(text: string): string {
  const normalized = normalizeContent(text);
  let hash = 0x811c9dc5;
  for (let index = 0; index < normalized.length; index += 1) {
    hash ^= normalized.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16);
}

/** 判据本体 (决策表见文件头)。 */
export function decideDiskAction(input: DiskCheckInput): DiskAction {
  const { diskHash, baseHash, memHash, dirty } = input;
  // 磁盘还是我们上次知道的那一份: 变的只可能是编辑器里的内容 (用户敲字 / 自动保存)
  if (baseHash !== undefined && diskHash === baseHash) return 'ignore';
  // 磁盘与编辑器一致: 可能就是我们自己的写盘, 也可能是别处写了同样的内容 —— 都不该打扰用户
  if (diskHash === memHash) return 'adopt';
  return dirty ? 'conflict' : 'reload';
}

/** 路径比较键 (Windows 大小写不敏感, 分隔符两种写法混用)。 */
export function pathKey(path: string): string {
  return path.replace(/\\/g, '/').toLowerCase();
}

/**
 * 一批监听事件涉及**哪些打开中的文档**。
 *
 * 事件没带路径 (`changedPaths` 为空) 时返回全部文档: 拿不到路径的监听实现并不少见, 宁可多读
 * 一遍, 也不要漏掉一次真实的变更。只做**整路径**匹配 —— 目录里某个文件变了, notify 报的是
 * 那个文件的路径, 不需要"前缀匹配目录"。
 */
export function affectedDocumentPaths(
  documents: readonly { path: string }[],
  changedPaths: readonly string[]
): string[] {
  if (changedPaths.length === 0) return documents.map((doc) => doc.path);
  const changed = new Set(changedPaths.map(pathKey));
  return documents.filter((doc) => changed.has(pathKey(doc.path))).map((doc) => doc.path);
}

/**
 * 对话框里的磁盘内容预览 (只取开头几行, 界面上放不下整份)。
 *
 * ⚠️ 预览**不能**当作"是否问过"的判据: 外部改动发生在第 13 行之后时预览一模一样,
 * 按预览去重就再也不会提示, 用户的改动会被静默丢掉。去重一律用全文哈希。
 */
export function previewOf(text: string, maxLines = 12): string {
  return text.split(/\r?\n/).slice(0, Math.max(1, maxLines)).join('\n');
}
